def to_roman(n: int) -> str:
    """
    Converts an integer (1 to 3999) to a Roman numeral string.
    """
    if not 1 <= n <= 3999:
        raise ValueError("Input must be between 1 and 3999")

    roman_map = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, symbol in roman_map:
        while n >= value:
            result.append(symbol)
            n -= value

    return "".join(result)

def spiral(m):
    if not m or not m[0]:
        return []

    rows = len(m)
    cols = len(m[0])
    result = []

    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while top <= bottom and left <= right:
        # 1. Traverse Right (Top row)
        for c in range(left, right + 1):
            result.append(m[top][c])
        top += 1

        # 2. Traverse Down (Right column)
        for r in range(top, bottom + 1):
            result.append(m[r][right])
        right -= 1

        # 3. Traverse Left (Bottom row) - Check if row still exists
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(m[bottom][c])
            bottom -= 1

        # 4. Traverse Up (Left column) - Check if column still exists
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(m[r][left])
            left += 1

    return result
